-- Laravel-pattern master COA. Only fixed Level 1-3 heads are seeded.
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE account_coa;
SET FOREIGN_KEY_CHECKS = 1;
DROP TABLE IF EXISTS account_coa;


UPDATE account_coa child JOIN account_coa parent ON parent.HeadName = child.PHeadName SET child.parent_id = parent.id WHERE child.PHeadName IS NOT NULL;
